bool process_record_user(uint16_t keycode, keyrecord_t *record) {
    uint16_t shortcut = KC_NO;
    switch (keycode) {
        case CF_FOCUS_UP:
            shortcut = LGUI(LALT(KC_UP));
            break;
        case CF_FOCUS_LEFT:
            shortcut = LGUI(LALT(KC_LEFT));
            break;
        case CF_FOCUS_DOWN:
            shortcut = LGUI(LALT(KC_DOWN));
            break;
        case CF_FOCUS_RIGHT:
            shortcut = LGUI(LALT(KC_RGHT));
            break;
        case CF_SCREEN_LEFT:
            shortcut = LGUI(LSFT(KC_LEFT));
            break;
        case CF_SCREEN_RIGHT:
            shortcut = LGUI(LSFT(KC_RGHT));
            break;
        default:
            return true;
    }
    if (record->event.pressed) {
        tap_code16(shortcut);
        wait_ms(CURSOR_FOLLOW_DELAY_MS);
        tap_code16(CURSOR_FOLLOW_THEN);
    }
    return false;
}

